import { ICON_FILES } from "./icon-names";
import { ICON_DATA } from "./icon-data";

export type { IconName } from "./icon-names";
export type IconWeight = "thin" | "light" | "regular" | "bold" | "fill" | "duotone";

/** Rendered weight → index into ICON_DATA ([regular, bold, fill]). Thin, light and duotone draw as regular. */
const WEIGHT_INDEX: Record<IconWeight, 0 | 1 | 2> = { thin: 0, light: 0, regular: 0, duotone: 0, bold: 1, fill: 2 };

/**
 * Line icons (Phosphor, https://phosphoricons.com) — clean, consistent strokes. Size in px.
 * Path data is generated by `npm run icons` for just the icons in icon-names.ts. Unknown names fall back to "sparkle".
 * `strokeWidth` is accepted for compatibility and ignored (Phosphor icons are filled outlines).
 */
export function Icon({ name, size = 18, className, weight = "regular" }: { name: string; size?: number; className?: string; weight?: IconWeight; strokeWidth?: number }) {
  const file = ICON_FILES[name as keyof typeof ICON_FILES] ?? ICON_FILES.sparkle;
  const d = ICON_DATA[file][WEIGHT_INDEX[weight] ?? 0];
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 256 256" fill="currentColor" className={className} aria-hidden="true" focusable="false">
      {d.map((p, i) => <path key={i} d={p} />)}
    </svg>
  );
}
